from itertools import product
G=[(0,1),(0,2),(0,4),(0,5), (1,0),(1,1),(1,2),(1,3),(1,4),(1,5), (2,1),(2,2),(2,4),(3,2),(3,3),(3,4)]
S=set(G)
# piece square + oriented L (bbox 2x2 missing corner); map missing TL=2, BL=3, TR=4, BR unknown likely 5
pieces=[]
for r in range(6):
 for c in range(6):
  sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if sq<=S: pieces.append((sq,1,'square'))
  for miss,col in [((0,0),2),((1,0),3),((0,1),4),((1,1),5)]:
   cells={(r+i,c+j) for i,j in product(range(2),range(2)) if (i,j)!=miss}
   if cells<=S: pieces.append((cells,col,str(miss)))
sol=[]
def rec(rem,chosen):
 if not rem:
  sol.append(chosen); return
 x=min(rem)
 for p in pieces:
  cells,col,name=p
  if x in cells and cells<=rem:
   rec(rem-cells,chosen+[p])
rec(S,[])
print('solutions',len(sol))
for s in sol[:10]: print([(sorted(x),col,n) for x,col,n in s])

